solutionCode:
pub fn voo(modo_eco: bool, bateria: i32) -> String {
    let limite = if modo_eco { 20 } else { 50 };
    if bateria == 0 {
        format!("bateria {bateria}: carregue antes de voar")
    } else if bateria < 0 {
        format!("bateria {bateria}: carga invalida")
    } else if bateria > limite {
        format!("bateria {bateria}: voo liberado")
    } else if !modo_eco && bateria > 20 {
        format!("bateria {bateria}: so no modo eco")
    } else {
        format!("bateria {bateria}: recarregue")
    }
}

testsCode:
use desafio::voo;

#[test]
fn testa_a_bateria_sem_carga() {
    assert_eq!(voo(false, 0), "bateria 0: carregue antes de voar");
}

#[test]
fn testa_a_bateria_negativa() {
    assert_eq!(voo(false, -7), "bateria -7: carga invalida");
}

#[test]
fn testa_o_voo_liberado_fora_do_eco() {
    assert_eq!(voo(false, 60), "bateria 60: voo liberado");
}

#[test]
fn testa_o_voo_liberado_no_eco() {
    assert_eq!(voo(true, 30), "bateria 30: voo liberado");
}

#[test]
fn testa_o_voo_que_somente_o_eco_aceita() {
    assert_eq!(voo(false, 30), "bateria 30: so no modo eco");
}

#[test]
fn testa_a_bateria_abaixo_do_minimo() {
    assert_eq!(voo(true, 10), "bateria 10: recarregue");
}
